<style lang="scss" src="./update-summary-editor.scss"></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import Divider from "../../components/divider/divider";
import {
  DividerMode,
  DividerSize,
} from "../../components/divider/divider.constants";
import UpdateSummaryEditorModal from "../../components/update-summary-editor-modal/update-summary-editor-modal";

/**
 * This component is used on a page where the user can input a new update
 * summary.
 */
@Component({
  components: {
    Divider,
    UpdateSummaryEditorModal,
  },
})
export default class UpdateSumaryEditor extends Vue {
  /**
   * Set this to true to include an image upload property
   */
  @Prop({ type: Boolean, default: false }) allowImageUpload;

  DividerMode = DividerMode;
  DividerSize = DividerSize;
  modalOpen = false;

  handleOpenModal() {
    this.modalOpen = true;
  }

  handleCloseModal() {
    this.modalOpen = false;
    /**
     * Emits when user closes the update summary modal.
     *
     * @event {close}
     */
    this.$emit("close");
  }

  handleUpdatePublish(title, image, summary) {
    /**
     * Emits all of the information in the update when the user clicks to
     * publish the change.
     *
     * Provides: (title, image, summary)
     *
     * @event update
     */
    this.$emit("update", title, image, summary);
    this.modalOpen = false;
  }
}
</script>

<template>
  <div class="UpdateSummaryEditor">
    <Divider
      :size="DividerSize.LARGE"
      :mode="DividerMode.HORIZONTAL_RULE_BUTTON"
      @click="handleOpenModal"
    >
      Add an Update
    </Divider>
    <UpdateSummaryEditorModal
      v-if="modalOpen"
      @close="handleCloseModal"
      @update="handleUpdatePublish"
      :allowImageUpload="allowImageUpload"
    />
  </div>
</template>
